using Microsoft.EntityFrameworkCore;using SPharmacyLog.Data;using SPharmacyLog.Data.Entities;namespace SPharmacyLog.Core;public class PharmacyAuthService{public async Task<bool> HasUsersAsync(){await using var db=new PharmacyDbContext(PharmacyDb.Options());return await db.Users.AnyAsync();}public async Task CreateFirstAdminAsync(string name,string password){if(string.IsNullOrWhiteSpace(name)||password.Length<8)throw new InvalidOperationException("Username required and password minimum 8 characters.");await using var db=new PharmacyDbContext(PharmacyDb.Options());if(await db.Users.AnyAsync())throw new InvalidOperationException("Admin already exists.");db.Users.Add(new PharmacyUser{Username=name.Trim(),PasswordHash=BCrypt.Net.BCrypt.HashPassword(password),Role=PharmacyRole.Admin});await db.SaveChangesAsync();}public async Task<PharmacyUser?> LoginAsync(string name,string password){await using var db=new PharmacyDbContext(PharmacyDb.Options());var u=await db.Users.FirstOrDefaultAsync(x=>x.Username==name.Trim()&&x.IsActive);return u!=null&&BCrypt.Net.BCrypt.Verify(password,u.PasswordHash)?u:null;}}public static class PharmacyDb{public static string PathDb=>System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SPharmacyLog","pharmacy.db");public static DbContextOptions<PharmacyDbContext> Options(){System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(PathDb)!);return new DbContextOptionsBuilder<PharmacyDbContext>().UseSqlite($"Data Source={PathDb};Foreign Keys=True").Options;}}